begin;

UPDATE questions SET disciplina = 'linguagens' WHERE disciplina IN ('portugues','literatura','artes') AND enunciado = 'Os melhores críticos da cultura brasileira trataram-na sempre no plural, isto é, enfatizando a coexistência no Brasil de diversas culturas. Arthur Ramos distingue as culturas não europeias (indígenas, negras) das europeias (portuguesa, italiana, alemã etc.), e Darcy Ribeiro fala de diversos Brasis: crioulo, caboclo, sertanejo, caipira e de Brasis sulinos, a cada um deles correspondendo uma cultura específica.

MORAIS, F. <strong>O Brasil na visão do artista: o país e sua cultura.</strong>  
São Paulo: Sudameris, 2003.';
UPDATE questions SET disciplina = 'linguagens' WHERE disciplina IN ('portugues','literatura','artes') AND enunciado = 'Gerente – Boa tarde. Em que eu posso ajudá-lo?  
Cliente – Estou interessado em financiamento para compra  
de veículo.  
Gerente – Nós dispomos de várias modalidades de crédito.  
O senhor é nosso cliente?  
Cliente – Sou Júlio César Fontoura, também sou  
funcionário do banco.  
Gerente – Julinho, é você, cara? Aqui é a Helena! Cê tá  
em Brasília? Pensei que você inda tivesse na agência de  
Uberlândia! Passa aqui pra gente conversar com calma.

BORTONI-RICARDO, S. M. <strong>Educação em língua materna.</strong>  
São Paulo: Parábola, 2004 (adaptado).';
